  "order-list-basic": "protected readonly basicProducts = signal<readonly Product[]>(this.createProducts());\n\nprotected readonly selectedBasic = signal<readonly string[]>(['keyboard']);\n\nprivate createProducts(): readonly Product[] {\n    return [\n      { id: 'monitor', label: 'Monitor', category: 'Hardware', stock: 'In stock' },\n      { id: 'keyboard', label: 'Keyboard', category: 'Hardware', stock: 'Low stock' },\n      { id: 'desk', label: 'Desk', category: 'Furniture', stock: 'In stock' },\n      { id: 'lamp', label: 'Desk lamp', category: 'Furniture', stock: 'In stock' },\n      { id: 'dock', label: 'Docking station', category: 'Hardware', stock: 'Backordered' },\n    ];\n  }",
  "order-list-events": "interface Product {\n  readonly id: string;\n  readonly label: string;\n  readonly category: string;\n  readonly stock: string;\n}\n\nprotected readonly basicProducts = signal<readonly Product[]>(this.createProducts());\n\nprotected readonly selectedBasic = signal<readonly string[]>(['keyboard']);\n\nprivate createProducts(): readonly Product[] {\n    return [\n      { id: 'monitor', label: 'Monitor', category: 'Hardware', stock: 'In stock' },\n      { id: 'keyboard', label: 'Keyboard', category: 'Hardware', stock: 'Low stock' },\n      { id: 'desk', label: 'Desk', category: 'Furniture', stock: 'In stock' },\n      { id: 'lamp', label: 'Desk lamp', category: 'Furniture', stock: 'In stock' },\n      { id: 'dock', label: 'Docking station', category: 'Hardware', stock: 'Backordered' },\n    ];\n  }",
  "order-list-scrolling": "interface Product {\n  readonly id: string;\n  readonly label: string;\n  readonly category: string;\n  readonly stock: string;\n}\n\nprotected readonly manyProducts = signal<readonly Product[]>(this.createManyProducts());\n\nprotected readonly selectedMany = signal<readonly string[]>(['item-6']);\n\nprivate createManyProducts(): readonly Product[] {\n    return Array.from({ length: 28 }, (_, index) => ({\n      id: `item-${index + 1}`,\n      label: `Queue item ${index + 1}`,\n      category: index % 2 === 0 ? 'Hardware' : 'Furniture',\n      stock: index % 3 === 0 ? 'Low stock' : 'In stock',\n    }));\n  }",
  "order-list-selection": "interface Product {\n  readonly id: string;\n  readonly label: string;\n  readonly category: string;\n  readonly stock: string;\n}\n\nprotected readonly templateProducts = signal<readonly Product[]>(this.createProducts());\n\nprotected readonly selectedTemplate = signal<readonly string[]>(['monitor', 'keyboard']);\n\nprivate createProducts(): readonly Product[] {\n    return [\n      { id: 'monitor', label: 'Monitor', category: 'Hardware', stock: 'In stock' },\n      { id: 'keyboard', label: 'Keyboard', category: 'Hardware', stock: 'Low stock' },\n      { id: 'desk', label: 'Desk', category: 'Furniture', stock: 'In stock' },\n      { id: 'lamp', label: 'Desk lamp', category: 'Furniture', stock: 'In stock' },\n      { id: 'dock', label: 'Docking station', category: 'Hardware', stock: 'Backordered' },\n    ];\n  }",
  "order-list-states": "interface Product {\n  readonly id: string;\n  readonly label: string;\n  readonly category: string;\n  readonly stock: string;\n}\n\nprotected readonly basicProducts = signal<readonly Product[]>(this.createProducts());\n\nprivate createProducts(): readonly Product[] {\n    return [\n      { id: 'monitor', label: 'Monitor', category: 'Hardware', stock: 'In stock' },\n      { id: 'keyboard', label: 'Keyboard', category: 'Hardware', stock: 'Low stock' },\n      { id: 'desk', label: 'Desk', category: 'Furniture', stock: 'In stock' },\n      { id: 'lamp', label: 'Desk lamp', category: 'Furniture', stock: 'In stock' },\n      { id: 'dock', label: 'Docking station', category: 'Hardware', stock: 'Backordered' },\n    ];\n  }",
  "organization-chart-collapsible": "interface Person {\n  readonly name: string;\n  readonly role: string;\n  readonly team: string;\n  readonly tone: 'sage' | 'blue' | 'gold' | 'rose';\n}\n\nprotected readonly chart = this.createChart();\n\nprotected readonly collapsed = signal<readonly string[]>(['ops']);\n\nprivate createChart(): readonly AerisOrganizationChartNode<Person>[] {\n    return [\n      {\n        key: 'ceo',\n        label: 'Maya Chen',\n        type: 'Executive',\n        data: this.person('Maya Chen', 'Chief Executive Officer', 'Leadership', 'sage'),\n        children: [\n          {\n            key: 'product',\n            label: 'Noah Williams',\n            type: 'Product',\n            data: this.person('Noah Williams', 'VP Product', 'Product', 'blue'),\n            children: [\n              { key: 'design', label: 'Lena Park', type: 'Design', data: this.person('Lena Park', 'Design Lead', 'Experience', 'rose') },\n              { key: 'research', label: 'Iris Novak', type: 'Research', data: this.person('Iris Novak', 'Research Lead', 'Insights', 'gold') },\n            ],\n          },\n          {\n            key: 'engineering',\n            label: 'Sofia Rossi',\n            type: 'Engineering',\n            data: this.person('Sofia Rossi', 'VP Engineering', 'Engineering', 'sage'),\n            children: [\n              { key: 'platform', label: 'Eli Brooks', type: 'Platform', data: this.person('Eli Brooks', 'Platform Lead', 'Core', 'blue') },\n              { key: 'quality', label: 'Ava Patel', type: 'Quality', data: this.person('Ava Patel', 'Quality Lead', 'QA', 'gold') },\n            ],\n          },\n          {\n            key: 'ops',\n            label: 'Liam Novak',\n            type: 'Operations',\n            data: this.person('Liam Novak', 'Operations Director', 'Operations', 'rose'),\n            children: [\n              { key: 'finance', label: 'Mila Costa', type: 'Finance', data: this.person('Mila Costa', 'Finance Lead', 'Finance', 'sage') },\n              { key: 'people', label: 'Theo Stone', type: 'People', data: this.person('Theo Stone', 'People Lead', 'People', 'blue') },\n            ],\n          },\n        ],\n      },\n    ];\n  }\n\nprivate person(name: string, role: string, team: string, tone: Person['tone']): Person {\n    return { name, role, team, tone };\n  }",
